// a defeat, step-by-step unlocks, entry/prize duels, war score per member, Partner Pool, starter pack, Gram Club,
// streak freeze, manual bonus, rewarded ads, opt-in reminders) and plural-safe counts. Merged over the other packs.

// Plural form for a count shown with n() (it may carry grouping or local digits): plural(k, one, other) or
// plural(k, one, few, many) for Slavic languages.
const PLURAL_RULES = {};
function plural(num, ...forms) {
  const v = +String(num).replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/\D/g, '') || 0;
  let r = v === 1 ? 'one' : 'other';
  try { r = (PLURAL_RULES[LANG] || (PLURAL_RULES[LANG] = new Intl.PluralRules(LANG))).select(v); } catch (e) {}
  if (forms.length === 2) return r === 'one' ? forms[0] : forms[1];
  return r === 'one' ? forms[0] : r === 'few' ? forms[1] : forms[2];
}

