    clubTitle: 'Gram Club', clubNote: (g, h) => `Jeden Tag 💎 ${g} und eine ${h}-Stunden-Ruhetruhe. Verlängert sich monatlich mit Telegram Stars; jederzeit in Telegram kündbar.`,
    clubBuy: s => `Beitreten · ⭐ ${s} / Monat`, clubClaim: g => `Heutige 💎 ${g} abholen`, clubDays: d => `Noch ${d} ${plural(d, 'Tag', 'Tage')}`, clubOn: 'Willkommen im Club! Hol dir deine Edelsteine jeden Tag unter Aufgaben.',
    freezeReady: 'Serien-Freeze bereit: Ein verpasster Tag diese Woche bricht deine Serie nicht.', freezeUsedWeek: 'Serien-Freeze diese Woche genutzt — er kommt am Montag zurück.', freezeUsed: 'Serien-Freeze genutzt — deine Serie ist sicher!',
